package dev.chyken.assembl_ar;
import android.os.*;import android.widget.*;import android.view.View;import java.util.*;
import androidx.appcompat.app.AppCompatActivity;import dev.chyken.assembl_ar.ui.*;import dev.chyken.assembl_ar.workflow.phase.*;import dev.chyken.assembl_ar.camera.Phase2AssetCatalog;import dev.chyken.assembl_ar.data.NeobotSeedData;
/** Read-only visual learning trail; opening it never modifies verified progress. */
public final class AssemblyRetrospectiveActivity extends AppCompatActivity {
    private int index;private TextView title,body;private ImageView image;private Button previous,next;private AssemblyVoiceGuide voice;private WiringDiagramReviewDialog wiring;
    private static final String[] WHY={
        "The main board is the mechanical base and distributes connections. A clean, non-metal surface helps prevent unintended electrical contact.",
        "Bracket pairs locate the gear motors. Inward-facing terminals protect wiring; firm joints keep the wheel shafts aligned under load.",
        "The motor driver switches the higher motor current in response to low-current control signals from the Nano. Proper seating and screws maintain electrical contact.",
        "Each motor uses a pair of driver outputs. Reversing current reverses its direction. Wire color is a visual aid; the connected terminals determine behavior.",
        "The Nano runs the control program. Its USB port is the orientation marker; every pin must enter its matching socket rather than an adjacent hole.",
        "Driver VCC connects to VIN and GND shares a reference. D5/D9 and D6/D10 control the two motor channels with PWM. Follow the saved schematic for the exact pins.",
        "The caster supports the chassis while swiveling. Spacers set the line trackers below the board so their infrared emitters and receivers can observe the floor.",
        "Ultrasound uses a Trigger pulse and Echo timing to estimate distance. Sensor power and ground are already connected by the PCB. Trackers report reflectance on A2/A3; LED A1 and speaker D3 provide feedback.",
        "The center standoff spaces and supports the upper board. Both wheel hubs must grip the motor D-shafts; appearance alone cannot prove that grip, which is why the physical check matters.",
        "The extension board adds a protected OLED socket and upper mounting surface. The data cable carries the signals between boards. Keep supports level and wiring clear of the board edges.",
        "The OLED uses the I2C clock and data lines, SCL and SDA. Securing the battery prevents motion and strain on its connector. Keep power off while changing connections; use the marked slider to power the completed robot."};
    @Override public void onCreate(Bundle state){super.onCreate(state);UiUtils.configureStandardWindow(this);if(state!=null)index=Math.max(0,Math.min(10,state.getInt("phase")));LinearLayout root=LearningWorkspaceUi.column(this);root.addView(LearningWorkspaceUi.text(this,"Assembly retrospective",28));root.addView(LearningWorkspaceUi.text(this,"Review what each component does and why each installation check matters. Your assembly progress stays saved.",15));title=LearningWorkspaceUi.text(this,"",22);root.addView(title);image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);root.addView(image,new LinearLayout.LayoutParams(-1,UiUtils.dp(this,230)));body=LearningWorkspaceUi.text(this,"",17);root.addView(body);LinearLayout nav=new LinearLayout(this);previous=LearningWorkspaceUi.button(this,"Previous",()->{index--;render();});next=LearningWorkspaceUi.button(this,"Next",()->{index++;render();});nav.addView(previous,new LinearLayout.LayoutParams(0,-2,1));nav.addView(next,new LinearLayout.LayoutParams(0,-2,1));root.addView(nav);root.addView(LearningWorkspaceUi.button(this,"Review saved wiring diagrams",this::schematics));root.addView(LearningWorkspaceUi.button(this,"Back",this::finish));setContentView(LearningWorkspaceUi.scroll(this,root));UiUtils.applyStandardInsets(this);voice=new AssemblyVoiceGuide(this,s->{});render();}
    private void render(){AssemblyPhase phase=AssemblyPhaseCatalog.phases().get(index);title.setText("Phase "+(index+1)+" · "+phase.getTitle());body.setText(PhaseGuideMetadata.summary(phase)+"\n\n"+WHY[index]);previous.setEnabled(index>0);next.setEnabled(index<10);String guide=null;for(String path:Phase2AssetCatalog.files(getAssets(),"references/Phase"+(index+1)))if(Phase2AssetCatalog.image(path)&&path.toUpperCase(Locale.ROOT).contains("SCANNINGGUIDE")){guide=path;break;}image.setVisibility(guide==null?View.GONE:View.VISIBLE);image.setContentDescription("Reference illustration for phase "+(index+1));AssetImageLoader.loadBounded(image,guide,1400);if(voice!=null)voice.speak(title.getText()+". "+body.getText(),"retrospective:"+index);}
    private void schematics(){WiringDiagramState state=WiringDiagramState.fromCheckpoints(PhaseProgressStore.wiringState(this,NeobotSeedData.PROJECT_ID),PhaseProgressStore.driverWiringState(this,NeobotSeedData.PROJECT_ID),PhaseProgressStore.sensorWiringState(this,NeobotSeedData.PROJECT_ID));wiring=new WiringDiagramReviewDialog(this,state,index+1,text->voice.speak(text,"retrospective:wire:"+SystemClock.elapsedRealtimeNanos()));wiring.show();}
    @Override protected void onSaveInstanceState(Bundle state){state.putInt("phase",index);super.onSaveInstanceState(state);}
    @Override protected void onPause(){if(wiring!=null)wiring.dismiss();if(voice!=null)voice.stop();super.onPause();}@Override protected void onDestroy(){if(voice!=null)voice.close();super.onDestroy();}
}
